'use server';

import { promises as fs } from 'fs';
import path from 'path';
import { revalidatePath } from 'next/cache';
import type { Tool, Tab, Panel } from '@/lib/tools-data';
import { defaultToolIds } from '@/lib/tools-data';

const customToolsPath = path.join(process.cwd(), 'src', 'lib', 'custom-tools.json');

async function readCustomTools(): Promise<Tool[]> {
    try {
        await fs.access(customToolsPath);
    } catch (error) {
        // If the file doesn't exist, create it with an empty array.
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
            await writeCustomTools([]);
            return [];
        }
        console.error("Error accessing custom tools file:", error);
        throw error;
    }

    try {
        const data = await fs.readFile(customToolsPath, 'utf-8');
        // If the file is empty, return an empty array.
        if (!data) {
            return [];
        }
        const tools = JSON.parse(data);
        return tools.map((t: Omit<Tool, 'icon'>) => ({...t, icon: 'Component'}));
    } catch (error) {
        console.error("Error reading or parsing custom tools:", error);
        // If parsing fails, it might be an empty or corrupted file.
        // It's safer to return an empty array and let the next write operation fix it.
        return [];
    }
}

async function writeCustomTools(tools: Tool[]) {
    // We need to store the icon as a string name, not a function.
    const storableTools = tools.map(tool => {
        const { icon, ...rest } = tool;
        const iconName = typeof icon === 'string' ? icon : (icon as any)?.displayName || 'Component';
        return { ...rest, icon: iconName };
    });
    await fs.writeFile(customToolsPath, JSON.stringify(storableTools, null, 2));
}

export async function saveTool(toolJSON: string) {
  try {
    const tools = await readCustomTools();
    const newTool = JSON.parse(toolJSON);

    const toolIndex = tools.findIndex(tool => tool.id === newTool.id);
    if (toolIndex !== -1) {
      tools[toolIndex] = newTool;
    } else {
        tools.push(newTool);
    }

    await writeCustomTools(tools);
    revalidatePath('/', 'layout');
    revalidatePath(`/${newTool.id}`);

    return { success: true, toolId: newTool.id };
  } catch (error) {
    console.error('Failed to save tool:', error);
    return { success: false, error: 'Failed to save the tool.' };
  }
}

export async function updatePanelContent(toolId: string, tabId: string, panelId: string, newContent: string) {
    if (defaultToolIds.includes(toolId)) {
        return { success: true };
    }

    try {
        const tools = await readCustomTools();
        const toolIndex = tools.findIndex(t => t.id === toolId);

        if (toolIndex === -1) {
            return { success: false, error: 'Tool not found.' };
        }

        const tabIndex = tools[toolIndex].layout.findIndex(t => t.id === tabId);
        if (tabIndex === -1) {
            return { success: false, error: 'Tab not found.' };
        }

        const panelIndex = tools[toolIndex].layout[tabIndex].panels.findIndex(p => p.id === panelId);
        if (panelIndex === -1) {
            return { success: false, error: 'Panel not found.' };
        }

        tools[toolIndex].layout[tabIndex].panels[panelIndex].content = newContent;

        await writeCustomTools(tools);
        revalidatePath(`/${toolId}`);

        return { success: true };
    } catch (error) {
        console.error('Failed to update panel content:', error);
        return { success: false, error: 'Failed to update panel content.' };
    }
}

export async function deleteTool(toolId: string) {
    try {
        if (defaultToolIds.includes(toolId)) {
            revalidatePath('/', 'layout');
            return { success: true };
        }

        let tools = await readCustomTools();
        const initialLength = tools.length;
        tools = tools.filter(t => t.id !== toolId);

        if (tools.length === initialLength) {
            return { success: false, error: 'Custom tool not found.' };
        }

        await writeCustomTools(tools);
        revalidatePath('/', 'layout');

        return { success: true };
    } catch (error) {
        console.error('Failed to delete tool:', error);
        return { success: false, error: 'Failed to delete the tool.' };
    }
}

export async function addTab(toolId: string, tabName: string) {
    if (defaultToolIds.includes(toolId)) {
        return { success: false, error: 'Cannot add tabs to a default tool.' };
    }
    try {
        const tools = await readCustomTools();
        const toolIndex = tools.findIndex(t => t.id === toolId);

        if (toolIndex === -1) {
            return { success: false, error: 'Tool not found.' };
        }

        const newTab: Tab = {
            id: `tab-${Date.now()}`,
            name: tabName,
            panels: [{
                id: `panel-${Date.now()}`,
                title: 'New Editor',
                type: 'editor',
                content: '',
                purpose: 'A new editor panel.'
            }]
        };

        tools[toolIndex].layout.push(newTab);
        await writeCustomTools(tools);
        revalidatePath(`/${toolId}`);

        return { success: true, newTab };
    } catch (error) {
        console.error('Failed to add tab:', error);
        return { success: false, error: 'Failed to add a new tab.' };
    }
}

export async function deleteTab(toolId: string, tabId: string) {
     if (defaultToolIds.includes(toolId)) {
        return { success: false, error: 'Cannot delete tabs from a default tool.' };
    }
    try {
        const tools = await readCustomTools();
        const toolIndex = tools.findIndex(t => t.id === toolId);

        if (toolIndex === -1) {
            return { success: false, error: 'Tool not found.' };
        }

        const initialTabCount = tools[toolIndex].layout.length;
        tools[toolIndex].layout = tools[toolIndex].layout.filter(t => t.id !== tabId);

        if (tools[toolIndex].layout.length === initialTabCount) {
             return { success: false, error: 'Tab not found.' };
        }

        await writeCustomTools(tools);
        revalidatePath(`/${toolId}`);
        revalidatePath('/', 'layout');


        return { success: true };
    } catch (error) {
        console.error('Failed to delete tab:', error);
        return { success: false, error: 'Failed to delete the tab.' };
    }
}

export async function addPanel(toolId: string, tabId: string, panelData: Omit<Panel, 'id' | 'content'>) {
    if (defaultToolIds.includes(toolId)) {
        return { success: false, error: 'Cannot add panels to a default tool.' };
    }
    try {
        const tools = await readCustomTools();
        const toolIndex = tools.findIndex(t => t.id === toolId);
        if (toolIndex === -1) return { success: false, error: 'Tool not found.' };

        const tabIndex = tools[toolIndex].layout.findIndex(t => t.id === tabId);
        if (tabIndex === -1) return { success: false, error: 'Tab not found.' };

        const newPanel: Panel = {
            ...panelData,
            id: `panel-${Date.now()}`,
            content: panelData.type === 'media' ? '' : `new_${panelData.type}_content`,
        };

        tools[toolIndex].layout[tabIndex].panels.push(newPanel);
        await writeCustomTools(tools);
        revalidatePath(`/${toolId}`);

        return { success: true, newPanel };
    } catch (error) {
        console.error('Failed to add panel:', error);
        return { success: false, error: 'Failed to add a new panel.' };
    }
}

export async function deletePanel(toolId: string, tabId: string, panelId: string) {
    if (defaultToolIds.includes(toolId)) {
        return { success: false, error: 'Cannot delete panels from a default tool.' };
    }
    try {
        const tools = await readCustomTools();
        const toolIndex = tools.findIndex(t => t.id === toolId);
        if (toolIndex === -1) return { success: false, error: 'Tool not found.' };

        const tabIndex = tools[toolIndex].layout.findIndex(t => t.id === tabId);
        if (tabIndex === -1) return { success: false, error: 'Tab not found.' };

        const initialPanelCount = tools[toolIndex].layout[tabIndex].panels.length;
        tools[toolIndex].layout[tabIndex].panels = tools[toolIndex].layout[tabIndex].panels.filter(p => p.id !== panelId);

        if (tools[toolIndex].layout[tabIndex].panels.length === initialPanelCount) {
            return { success: false, error: 'Panel not found.' };
        }
        
        await writeCustomTools(tools);
        revalidatePath(`/${toolId}`);

        return { success: true };
    } catch (error) {
        console.error('Failed to delete panel:', error);
        return { success: false, error: 'Failed to delete the panel.' };
    }
}
