'use client';

import { usePathname, useRouter } from 'next/navigation';
import Link from 'next/link';
import { tools } from '@/lib/tools-data';
import {
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarMenuAction,
} from '@/components/ui/sidebar';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { useState, useTransition } from 'react';
import { deleteTool } from '@/app/actions';
import { useToast } from '@/hooks/use-toast';
import { Trash2 } from 'lucide-react';

export function ForgeSidebarMenu() {
  const pathname = usePathname();
  const router = useRouter();
  const { toast } = useToast();
  const [isPending, startTransition] = useTransition();
  const [dialogOpen, setDialogOpen] = useState(false);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  const handleDeleteClick = (e: React.MouseEvent, toolId: string) => {
    e.preventDefault();
    e.stopPropagation();
    setToolToDelete(toolId);
    setDialogOpen(true);
  };

  const handleConfirmDelete = () => {
    if (!toolToDelete) return;

    startTransition(async () => {
      const result = await deleteTool(toolToDelete);
      if (result.success) {
        toast({
          title: 'Tool Deleted',
          description: 'The tool has been successfully removed.',
        });
        // If the current page is the one being deleted, navigate home
        if (pathname === `/${toolToDelete}`) {
          router.push('/');
        }
      } else {
        toast({
          variant: 'destructive',
          title: 'Error',
          description: result.error || 'Failed to delete the tool.',
        });
      }
      setDialogOpen(false);
      setToolToDelete(null);
    });
  };

  return (
    <>
      <SidebarMenu>
        {tools.map((tool) => {
          return (
            <SidebarMenuItem key={tool.id}>
              <SidebarMenuButton
                asChild
                isActive={pathname === `/${tool.id}`}
                tooltip={tool.name}
              >
                <Link href={`/${tool.id}`}>
                  <tool.icon />
                  <span>{tool.name}</span>
                </Link>
              </SidebarMenuButton>
              <SidebarMenuAction
                showOnHover
                onClick={(e) => handleDeleteClick(e, tool.id)}
                aria-label={`Delete ${tool.name}`}
              >
                <Trash2 />
              </SidebarMenuAction>
            </SidebarMenuItem>
          );
        })}
      </SidebarMenu>
      <AlertDialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. This will permanently delete your
              tool and all of its data.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmDelete} disabled={isPending}>
              {isPending ? 'Deleting...' : 'Delete'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}
