'use client';

import { useState, useTransition } from 'react';
import { Plus } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Button } from '@/components/ui/button';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { generateToolOutline } from '@/ai/flows/generate-tool-outline';
import { useToast } from '@/hooks/use-toast';
import { Loader2 } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { saveTool } from '@/app/actions';
import { Textarea } from '../ui/textarea';

const NewToolSchema = z.object({
  topic: z
    .string()
    .min(10, 'Please provide a more detailed description.')
    .max(500, 'Description is too long.'),
});

type NewToolFormValues = z.infer<typeof NewToolSchema>;

export function NewTool() {
  const [open, setOpen] = useState(false);
  const [isPending, startTransition] = useTransition();
  const { toast } = useToast();
  const router = useRouter();

  const form = useForm<NewToolFormValues>({
    resolver: zodResolver(NewToolSchema),
    defaultValues: {
      topic: '',
    },
  });

  const onSubmit = async (values: NewToolFormValues) => {
    startTransition(async () => {
      try {
        const { outline } = await generateToolOutline({ topic: values.topic });
        const result = await saveTool(outline);

        if (result.success) {
          toast({
            title: 'Tool Created!',
            description: 'Your new tool has been added to the sidebar.',
          });
          setOpen(false);
          form.reset();
          // The revalidatePath in the action handles refreshing the data
          router.push(`/${result.toolId}`);
        } else {
          throw new Error(result.error);
        }
      } catch (error) {
        console.error('Failed to create new tool:', error);
        toast({
          variant: 'destructive',
          title: 'Error',
          description:
            error instanceof Error
              ? error.message
              : 'Failed to create new tool. Please try again.',
        });
      }
    });
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="ghost" className="w-full justify-start">
          <Plus className="mr-2" />
          New Tool
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Create a New Tool with AI</DialogTitle>
          <DialogDescription>
            Describe the tool you want to create. Be specific about the tabs,
            panels, and their types.
          </DialogDescription>
        </DialogHeader>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="topic"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Tool Description</FormLabel>
                  <FormControl>
                    <Textarea
                      placeholder="e.g., 'A tool for writing a travel blog. It should have two tabs: a 'Destinations' tab with an editor for notes and a media panel for inspiration photos, and a 'Drafts' tab with a main editor for writing the blog post.'"
                      className="min-h-[120px]"
                      {...field}
                    />
                  </FormControl>
                  <FormDescription>
                    The AI will generate the tool's structure based on your
                    description.
                  </FormDescription>
                  <FormMessage />
                </FormItem>
              )}
            />
            <Button type="submit" disabled={isPending}>
              {isPending && <Loader2 className="mr-2 animate-spin" />}
              Generate Tool
            </Button>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}
